#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 998244353;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<ll> w(n+1), s(n+1);
    for(int i = 1; i <= n; i++){
        cin >> w[i];
        s[i] = s[i-1] + w[i];
    }

    __int128 max_prod = 0;
    // 枚举第二个切割点 q (2 <= q <= n-1)
    for(int q = 2; q < n; q++){
        ll T = s[q];                     // 前两段总和
        // 在 s[1..q-1] 中二分查找第一个 >= T/2 的位置
        int pos = lower_bound(s.begin()+1, s.begin()+q, T/2.0) - s.begin();
        // 检查 pos 和 pos-1
        for(int p = pos; p >= pos-1 && p >= 1; p--){
            if(p < q){
                __int128 prod = (__int128)s[p] * (T - s[p]) * (s[n] - T);
                if(prod > max_prod) max_prod = prod;
            }
        }
    }

    ll ans = (ll)(max_prod % MOD);
    cout << ans << "\n";
    return 0;
}
